/**
 * @typedef {object} CellWriteResult
 * @property {string} updatedAt
 * @property {CellChange[]} changes
 * @property {CellCoord[]} removed
 * @property {number} rowCount
 * @property {number} colCount
 */

/**
 * Size a write needs, or throw when the target is beyond the supported limits.
 * `raw === ''` only ever deletes, so clearing never grows a worksheet.
 *
 * @param {WorksheetRow} ws
 * @param {CellChange[]} changes
 * @returns {{
 *   rowCount: number,
 *   colCount: number,
 *   rowsToAdd: number,
 *   colsToAdd: number,
 *   overflow: { row: number, col: number } | null,
 * }}
 */
function planGrowth(ws, changes) {
  let maxRow = ws.row_count - 1;
  let maxCol = ws.col_count - 1;
  let overflow = /** @type {{ row: number, col: number } | null} */ (null);
  for (const change of changes) {
    if (change.raw === '') continue;
    if (change.row >= MAX_ROW_COUNT || change.col >= MAX_COL_COUNT) {
      overflow = { row: change.row, col: change.col };
      continue;
    }
    if (change.row > maxRow) maxRow = change.row;
    if (change.col > maxCol) maxCol = change.col;
  }
  return {
    rowCount: maxRow + 1,
    colCount: maxCol + 1,
    rowsToAdd: Math.max(0, maxRow + 1 - ws.row_count),
    colsToAdd: Math.max(0, maxCol + 1 - ws.col_count),
    overflow,
  };
}

/**
 * Apply a batch of cell writes atomically. `raw === ''` clears the cell.
 * All-or-nothing: validation must have rejected the batch before this runs.
 *
 * Writing outside the current structure grows `row_count`/`col_count` in the
 * same transaction (Google Sheets semantics), so pasting a block that overflows
 * the sheet succeeds and stays consistent with what the snapshot reports.
 *
 * @param {Db} db
 * @param {WorksheetRow} ws
 * @param {CellChange[]} changes
 * @returns {CellWriteResult}
 */
export function applyCellChanges(db, ws, changes) {
  const at = nowIso();
  const growth = planGrowth(ws, changes);
  if (growth.overflow) {
    throw invalidBody(
      `Cell ${growth.overflow.row},${growth.overflow.col} is outside the supported worksheet size (max ${MAX_ROW_COUNT}x${MAX_COL_COUNT})`,
    );
  }
  const upsert = db.prepare(
    `INSERT INTO cells (worksheet_id, row, col, raw) VALUES (?, ?, ?, ?)
     ON CONFLICT (worksheet_id, row, col) DO UPDATE SET raw = excluded.raw`,
  );
  const remove = db.prepare('DELETE FROM cells WHERE worksheet_id = ? AND row = ? AND col = ?');
  /** @type {CellChange[]} */
  const written = [];
  /** @type {CellCoord[]} */
  const removed = [];
  db.transaction(() => {
    if (growth.rowsToAdd > 0 || growth.colsToAdd > 0) {
      db.prepare('UPDATE worksheets SET row_count = ?, col_count = ? WHERE id = ?').run(
        growth.rowCount,
        growth.colCount,
        ws.id,
      );
    }
    for (const change of changes) {
      if (change.raw === '') {
        remove.run(ws.id, change.row, change.col);
        removed.push({ row: change.row, col: change.col });
      } else {
        upsert.run(ws.id, change.row, change.col, change.raw);
        written.push(change);
      }
    }
    touchWorkbook(db, ws.workbook_id, at);
  })();
  return {
    updatedAt: at,
    changes: written,
    removed,
    rowCount: growth.rowCount,
    colCount: growth.colCount,
  };
}

