    if (col > maxCol) maxCol = col;
    insert.run(ws.id, row, col, raw);
  }
  // A replayed snapshot must never store cells the reported structure
  // cannot show: grow to fit (never shrink) in the same transaction.
  const current = /** @type {WorksheetRow} */ (
    db.prepare('SELECT * FROM worksheets WHERE id = ?').get(ws.id)
  );
  if (maxRow + 1 > current.row_count || maxCol + 1 > current.col_count) {
    db.prepare('UPDATE worksheets SET row_count = ?, col_count = ? WHERE id = ?').run(
      Math.max(current.row_count, maxRow + 1),
      Math.max(current.col_count, maxCol + 1),
      ws.id,
    );
  }
}

